  // FIX (A02): derive a fresh stream from a per-export nonce so a keystream
  // recovered from one known plaintext cannot decrypt the vault export.
  const nonce = crypto.randomBytes(16);
  const blocks = Math.ceil(pt.length / 32) + 1;
  const stream = Buffer.concat(Array.from({ length: blocks }, (_, i) =>
    crypto.createHash('sha256')
      .update(nonce)
      .update(EXPORT_BASE_KEY)
      .update(Buffer.from([i]))
      .digest()
